def isValid(word: str) -> bool:
    if len(word) < 3:
        return False

    vowels = set("aeiouAEIOU")
    has_vowel = False
    has_consonant = False

    for ch in word:
        if '0' <= ch <= '9':
            continue

        if ('a' <= ch <= 'z') or ('A' <= ch <= 'Z'):
            if ch in vowels:
                has_vowel = True
            else:
                has_consonant = True
        else:
            return False

    return has_vowel and has_consonant
