def lastNonEmptyString(s: str) -> str:
    freq = [0] * 26
    last_pos = [-1] * 26

    for i, ch in enumerate(s):
        idx = ord(ch) - ord('a')
        freq[idx] += 1
        last_pos[idx] = i

    max_freq = max(freq)

    result = []
    for idx in range(26):
        if freq[idx] == max_freq:
            result.append((last_pos[idx], chr(idx + ord('a'))))

    result.sort()
    return ''.join(ch for _, ch in result)
```

