def make_palindrome(s: str) -> str:
    chars = list(s)
    left, right = 0, len(chars) - 1

    while left < right:
        if chars[left] != chars[right]:
            smaller = min(chars[left], chars[right])
            chars[left] = smaller
            chars[right] = smaller
        left += 1
        right -= 1

    return "".join(chars)
```

