import sys

def solve():
    data = sys.stdin.read().split()

    pieces = []
    for i in range(3):
        cells = set()
        for r in range(4):
            for c, ch in enumerate(data[i * 4 + r]):
                if ch == "#":
                    cells.add((r, c))
        pieces.append(cells)

    FULL = (1 << 16) - 1

    def normalize(cells):
        min_r = min(r for r, _ in cells)
        min_c = min(c for _, c in cells)
        return tuple(sorted((r - min_r, c - min_c) for r, c in cells))

    def rotate90(cells):
        return {(c, -r) for r, c in cells}

    def make_placements(cells):
        rotations = set()
        cur = cells

        for _ in range(4):
            rotations.add(normalize(cur))
            cur = rotate90(cur)

        placements = set()

        for shape in rotations:
            height = max(r for r, _ in shape) + 1
            width = max(c for _, c in shape) + 1

            for dr in range(5 - height):
                for dc in range(5 - width):
                    mask = 0
                    for r, c in shape:
                        mask |= 1 << ((r + dr) * 4 + (c + dc))
                    placements.add(mask)

        return list(placements)

    all_placements = [make_placements(piece) for piece in pieces]

    for p1 in all_placements[0]:
        for p2 in all_placements[1]:
            if p1 & p2:
                continue

            used = p1 | p2

            for p3 in all_placements[2]:
                if (used & p3) == 0 and (used | p3) == FULL:
                    print("Yes")
                    return

    print("No")

solve()
