    if not data:
        return

    V1, V2, V3 = data[0], data[1], data[2]
    BASE = 3 * 7 ** 3

    # Necessary relation:
    # sum of pairwise intersection volumes = V2 + 3*V3
    # V1 = BASE - 2*V2 - 3*V3
    if V1 != BASE - 2 * V2 - 3 * V3:
        print("No")
        return

    target_pair_sum = V2 + 3 * V3

    # Precompute all possible one-dimensional states.
    # State: (overlap12, overlap13, overlap23, pos1, pos2, pos3)
    states = [[] for _ in range(8)]
    seen = [set() for _ in range(8)]

    for x1 in range(15):
        for x2 in range(15):
            d12 = abs(x1 - x2)
            p12 = 7 - d12 if d12 < 7 else 0
            for x3 in range(15):
                d13 = abs(x1 - x3)
                d23 = abs(x2 - x3)
                p13 = 7 - d13 if d13 < 7 else 0
                p23 = 7 - d23 if d23 < 7 else 0

                rng = max(x1, x2, x3) - min(x1, x2, x3)
                t = 7 - rng if rng < 7 else 0

                key = (p12, p13, p23)
                if key not in seen[t]:
                    seen[t].add(key)
                    states[t].append((p12, p13, p23, x1, x2, x3))

    if V3 == 0:
        t_triples = [
            (tx, ty, tz)
            for tx in range(8)
            for ty in range(8)
            for tz in range(8)
            if tx * ty * tz == 0
        ]
    else:
        t_triples = [
            (tx, ty, tz)
            for tx in range(1, 8)
            for ty in range(1, 8)
            for tz in range(1, 8)
            if tx * ty * tz == V3
        ]

    ans = None

    for tx, ty, tz in t_triples:
        for px12, px13, px23, x1, x2, x3 in states[tx]:
            for py12, py13, py23, y1, y2, y3 in states[ty]:
                w12 = px12 * py12
                w13 = px13 * py13
                w23 = px23 * py23

                for pz12, pz13, pz23, z1, z2, z3 in states[tz]:
                    if w12 * pz12 + w13 * pz13 + w23 * pz23 == target_pair_sum:
                        ans = (x1, y1, z1, x2, y2, z2, x3, y3, z3)
                        break
                if ans is not None:
                    break
            if ans is not None:
                break
        if ans is not None:
            break

    if ans is None:
        print("No")
    else:
