import sys

MOD = 998244353

def solve():
    input = sys.stdin.buffer.readline

    H, W = map(int, input().split())
    grid = [input().strip() for _ in range(H)]

    n = H * W
    comp_id = [-1] * n
    comp_count = 0

    # Label each green connected component.
    for si in range(H):
        for sj in range(W):
            start = si * W + sj
            if grid[si][sj] == ord('#') and comp_id[start] == -1:
                comp_count += 1
                comp_id[start] = comp_count
                queue = [start]
                head = 0

                while head < len(queue):
                    v = queue[head]
                    head += 1
                    x, y = divmod(v, W)

                    if x > 0:
                        nv = v - W
                        if comp_id[nv] == -1 and grid[x - 1][y] == ord('#'):
                            comp_id[nv] = comp_count
                            queue.append(nv)

                    if x + 1 < H:
                        nv = v + W
                        if comp_id[nv] == -1 and grid[x + 1][y] == ord('#'):
                            comp_id[nv] = comp_count
                            queue.append(nv)

                    if y > 0:
                        nv = v - 1
                        if comp_id[nv] == -1 and grid[x][y - 1] == ord('#'):
                            comp_id[nv] = comp_count
                            queue.append(nv)

                    if y + 1 < W:
                        nv = v + 1
                        if comp_id[nv] == -1 and grid[x][y + 1] == ord('#'):
                            comp_id[nv] = comp_count
                            queue.append(nv)

    red_count = 0
    total = 0
    base = comp_count + 1

    # For each red cell, new component count = comp_count + 1 - adjacent distinct components.
    for i in range(H):
        for j in range(W):
            if grid[i][j] == ord('.'):
                red_count += 1
                k = 0
                s1 = s2 = s3 = -1

                if i > 0:
                    lab = comp_id[(i - 1) * W + j]
                    if lab != -1:
                        s1 = lab
                        k = 1

                if i + 1 < H:
                    lab = comp_id[(i + 1) * W + j]
                    if lab != -1 and lab != s1:
                        s2 = lab
                        k += 1

                if j > 0:
                    lab = comp_id[i * W + j - 1]
                    if lab != -1 and lab != s1 and lab != s2:
                        s3 = lab
                        k += 1

                if j + 1 < W:
                    lab = comp_id[i * W + j + 1]
                    if lab != -1 and lab != s1 and lab != s2 and lab != s3:
                        k += 1

                total += base - k

    ans = (total % MOD) * pow(red_count, MOD - 2, MOD) % MOD
    print(ans)

solve()

