def numberOfRightTriangles(grid):
    m = len(grid)
    n = len(grid[0]) if m else 0

    row_count = [0] * m
    col_count = [0] * n

    for i in range(m):
        for j in range(n):
            if grid[i][j]:
                row_count[i] += 1
                col_count[j] += 1

    total = 0
    for i in range(m):
        row_choices = row_count[i] - 1
        if row_choices <= 0:
            continue
        for j in range(n):
            if grid[i][j]:
                total += row_choices * (col_count[j] - 1)

    return total
