def countBeautifulIntegers(low: int, high: int, k: int) -> int:
    from functools import lru_cache

    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0

        digits = list(map(int, str(n)))

        @lru_cache(None)
        def dp(pos: int, remainder: int, balance: int, started: bool) -> int:
            if pos == len(digits):
                return 1 if started and balance == 0 else 0

            limit = digits[pos]
            total = 0

            for d in range(limit + 1):
                if not started and d == 0:
                    total += dp(pos + 1, remainder, balance, False)
                else:
                    new_remainder = (remainder * 10 + d) % k
                    new_balance = balance + (1 if d % 2 == 0 else -1)
                    total += dp(pos + 1, new_remainder, new_balance, True)

            return total

        return dp(0, 0, 0, False)

    return count_up_to(high) - count_up_to(low - 1)
```

