import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N = data[0]

    g = [[] for _ in range(N)]
    idx = 1
    for _ in range(N - 1):
        u = data[idx] - 1
        v = data[idx + 1] - 1
        idx += 2
        g[u].append(v)
        g[v].append(u)

    parent = [-1] * N
    parent[0] = -2
    order = []
    stack = [0]
    while stack:
        v = stack.pop()
        order.append(v)
        for to in g[v]:
            if to == parent[v]:
                continue
            parent[to] = v
            stack.append(to)

    # f1[v]: v is an original star center
    # f00[v]: v is not a center and has 0 center-children
    # f01[v]: v is not a center and has 1 center-child
    f1 = [False] * N
    f00 = [False] * N
    f01 = [False] * N

    for v in reversed(order):
        deg = len(g[v])

        ok = deg >= 2
        if ok:
            for to in g[v]:
                if parent[to] == v and not f00[to]:
                    ok = False
                    break
        f1[v] = ok

        if deg <= 2:
            dp0 = True
            dp1 = False

            for to in g[v]:
                if parent[to] != v:
                    continue

                ndp0 = False
                ndp1 = False

                if f1[to] and dp0:
                    ndp1 = True
                if f01[to]:
                    if dp0:
                        ndp0 = True
                    if dp1:
                        ndp1 = True

                dp0, dp1 = ndp0, ndp1

            f00[v] = dp0
            f01[v] = dp1

    is_center = [False] * N

    if f1[0]:
        stack = [(0, True, 0)]
    else:
        stack = [(0, False, 1)]

    while stack:
        v, center, req = stack.pop()

        if center:
            is_center[v] = True
            for to in g[v]:
                if parent[to] == v:
                    stack.append((to, False, 0))
        else:
            if req == 1:
                chosen = -1

                for to in g[v]:
                    if parent[to] == v and not f01[to]:
                        chosen = to
                        break

                if chosen == -1:
                    for to in g[v]:
                        if parent[to] == v and f1[to]:
                            chosen = to
                            break

                for to in g[v]:
                    if parent[to] != v:
                        continue
                    if to == chosen:
                        stack.append((to, True, 0))
                    else:
                        stack.append((to, False, 1))
            else:
