def minimumTimeToInitialState(word: str, k: int) -> int:
    n = len(word)

    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        while j > 0 and word[i] != word[j]:
            j = pi[j - 1]
        if word[i] == word[j]:
            j += 1
        pi[i] = j

    m = pi[-1]
    while m > 0:
        if (n - m) % k == 0:
            return (n - m) // k
        m = pi[m - 1]

    return (n + k - 1) // k
