def minDistance(points):
    n = len(points)
    INF = 10**30
    worst_after_removal = [0] * n

    # Manhattan distance in 2D:
    # |x1-x2| + |y1-y2| = max(|(x+y)_1-(x+y)_2|, |(x-y)_1-(x-y)_2|)
    for sign in (1, -1):
        vals = [x + sign * y for x, y in points]

        mn1 = mn2 = INF
        mx1 = mx2 = -INF
        imn1 = imn2 = imx1 = imx2 = -1

        for i, v in enumerate(vals):
            if v < mn1:
                mn2, imn2 = mn1, imn1
                mn1, imn1 = v, i
            elif v < mn2:
                mn2, imn2 = v, i

            if v > mx1:
                mx2, imx2 = mx1, imx1
                mx1, imx1 = v, i
            elif v > mx2:
                mx2, imx2 = v, i

        for i in range(n):
            if i == imn1 and i == imx1:
                dist = mx2 - mn2
            elif i == imn1:
                dist = mx1 - mn2
            elif i == imx1:
                dist = mx2 - mn1
            else:
                dist = mx1 - mn1

            if dist > worst_after_removal[i]:
                worst_after_removal[i] = dist

    return min(worst_after_removal)
