import sys
from functools import lru_cache

def solve():
    a = list(map(int, sys.stdin.buffer.read().split()))

    lines = [
        (1 << 0) | (1 << 1) | (1 << 2),
        (1 << 3) | (1 << 4) | (1 << 5),
        (1 << 6) | (1 << 7) | (1 << 8),
        (1 << 0) | (1 << 3) | (1 << 6),
        (1 << 1) | (1 << 4) | (1 << 7),
        (1 << 2) | (1 << 5) | (1 << 8),
        (1 << 0) | (1 << 4) | (1 << 8),
        (1 << 2) | (1 << 4) | (1 << 6),
    ]
    full = (1 << 9) - 1

    @lru_cache(None)
    def takahashi_wins(red, blue):
        for line in lines:
            if red & line == line:
                return True
            if blue & line == line:
                return False

        used = red | blue
        if used == full:
            score = 0
            for i in range(9):
                if red >> i & 1:
                    score += a[i]
                else:
                    score -= a[i]
            return score > 0

        is_takahashi = used.bit_count() % 2 == 0

        if is_takahashi:
            for i in range(9):
                if not (used >> i & 1):
                    if takahashi_wins(red | (1 << i), blue):
                        return True
            return False
        else:
            for i in range(9):
                if not (used >> i & 1):
                    if not takahashi_wins(red, blue | (1 << i)):
                        return False
            return True

    print("Takahashi" if takahashi_wins(0, 0) else "Aoki")

solve()
