def sumImbalanceNumbers(nums):
    n = len(nums)
    if n <= 1:
        return 0

    values = sorted(set(nums))
    m = len(values)
    rank = {v: i + 1 for i, v in enumerate(values)}

    tree = [0] * (m + 2)
    present = [False] * (m + 2)

    def bit_add(i, delta):
        while i <= m:
            tree[i] += delta
            i += i & -i

    def bit_sum(i):
        total = 0
        while i > 0:
            total += tree[i]
            i -= i & -i
        return total

    highest_power = 1
    while highest_power * 2 <= m:
        highest_power *= 2

    def kth(k):
        idx = 0
        step = highest_power
        while step:
            nxt = idx + step
            if nxt <= m and tree[nxt] < k:
                idx = nxt
                k -= tree[nxt]
            step >>= 1
        return idx + 1

    answer = 0

    for left in range(n):
        tree = [0] * (m + 2)
        present = [False] * (m + 2)
        count = 0
        imbalance = 0

        for right in range(left, n):
            x = nums[right]
            r = rank[x]

            if not present[r]:
                before = bit_sum(r - 1)

                pred_rank = kth(before) if before else 0
                succ_rank = kth(before + 1) if before < count else 0

                pred = values[pred_rank - 1] if pred_rank else None
                succ = values[succ_rank - 1] if succ_rank else None

                if pred is not None and succ is not None:
                    if succ - pred > 1:
                        imbalance -= 1
                    if x - pred > 1:
                        imbalance += 1
                    if succ - x > 1:
                        imbalance += 1
                elif pred is not None:
                    if x - pred > 1:
                        imbalance += 1
                elif succ is not None:
                    if succ - x > 1:
                        imbalance += 1

                present[r] = True
                bit_add(r, 1)
                count += 1

            answer += imbalance

    return answer
