def min_changes(s, k):
    n = len(s)
    INF = 10**9

    cost = [[INF] * (n + 1) for _ in range(n + 1)]

    for length in range(2, n + 1):
        for left in range(n - length + 1):
            right = left + length
            best = INF

            for d in range(1, length):
                if length % d != 0:
                    continue

                changes = 0
                for rem in range(d):
                    i = left + rem
                    j = right - d + rem

                    while i < j:
                        if s[i] != s[j]:
                            changes += 1
                        i += d
                        j -= d

                best = min(best, changes)
                if best == 0:
                    break

            cost[left][right] = best

    prev = [INF] * (n + 1)
    prev[0] = 0

    for parts in range(1, k + 1):
        curr = [INF] * (n + 1)

        for end in range(2 * parts, n + 1):
            for start in range(2 * (parts - 1), end - 1):
                curr[end] = min(curr[end], prev[start] + cost[start][end])

        prev = curr

    return prev[n]
