def countSubmultisets(nums, l, r):
    MOD = 1_000_000_007

    if not nums:
        return 1 if l == 0 and r >= 0 else 0

    total = sum(nums)
    r = min(r, total)
    if l > r:
        return 0

    max_val = max(nums)
    freq = [0] * (max_val + 1)
    for x in nums:
        freq[x] += 1

    dp = [0] * (r + 1)
    dp[0] = 1

    for v, c in enumerate(freq):
        if v == 0 or c == 0 or v > r:
            continue

        ndp = [0] * (r + 1)

        for rem in range(min(v, r + 1)):
            window = 0

            for s in range(rem, r + 1, v):
                window += dp[s]
                if window >= MOD:
                    window -= MOD

                old = s - (c + 1) * v
                if old >= 0:
                    window -= dp[old]
                    if window < 0:
                        window += MOD

                ndp[s] = window

        dp = ndp

    ans = 0
    for s in range(l, r + 1):
        ans += dp[s]
        if ans >= MOD:
            ans -= MOD

    return ans * (freq[0] + 1) % MOD
```

