def minimizeStringValue(s: str) -> str:
    from heapq import heapify, heappop, heappush

    counts = [0] * 26
    question_count = 0

    for ch in s:
        if ch == '?':
            question_count += 1
        else:
            counts[ord(ch) - ord('a')] += 1

    heap = [(counts[i], i) for i in range(26)]
    heapify(heap)

    added = []
    for _ in range(question_count):
        cnt, idx = heappop(heap)
        added.append(idx)
        heappush(heap, (cnt + 1, idx))

    added.sort()

    result = list(s)
    j = 0
    for i, ch in enumerate(result):
        if ch == '?':
            result[i] = chr(ord('a') + added[j])
            j += 1

    return ''.join(result)
