def findPrimePairs(n):
    if n < 4:
        return []

    is_prime = bytearray(b'\x01') * (n + 1)
    is_prime[0] = is_prime[1] = 0

    p = 2
    while p * p <= n:
        if is_prime[p]:
            start = p * p
            is_prime[start:n + 1:p] = b'\x00' * (((n - start) // p) + 1)
        p += 1

    pairs = []
    for x in range(2, n // 2 + 1):
        y = n - x
        if is_prime[x] and is_prime[y]:
            pairs.append([x, y])

    return pairs
