def minAnagramLength(s: str) -> int:
    from math import gcd

    n = len(s)
    arr = [ord(ch) - 97 for ch in s]

    total = [0] * 26
    for x in arr:
        total[x] += 1

    g = 0
    for c in total:
        g = gcd(g, c)

    divisors = []
    d = 1
    while d * d <= g:
        if g % d == 0:
            divisors.append(d)
            other = g // d
            if other != d:
                divisors.append(other)
        d += 1

    divisors.sort(reverse=True)

    for blocks in divisors:
        k = n // blocks

        target = [0] * 26
        for i in range(k):
            target[arr[i]] += 1

        ok = True
        for b in range(1, blocks):
            start = b * k
            cnt = [0] * 26

            for i in range(start, start + k):
                cnt[arr[i]] += 1

            if cnt != target:
                ok = False
                break

        if ok:
            return k

    return n
