def medianUniqueness(nums):
    n = len(nums)
    if n == 0:
        return 0

    total_subarrays = n * (n + 1) // 2
    needed = (total_subarrays + 1) // 2

    def has_enough_with_at_most(k):
        freq = {}
        left = 0
        distinct = 0
        count = 0

        for right in range(n):
            x = nums[right]
            if freq.get(x, 0) == 0:
                distinct += 1
            freq[x] = freq.get(x, 0) + 1

            while distinct > k:
                y = nums[left]
                freq[y] -= 1
                if freq[y] == 0:
                    del freq[y]
                    distinct -= 1
                left += 1

            count += right - left + 1
            if count >= needed:
                return True

        return False

    low, high = 1, n
    answer = n

    while low <= high:
        mid = (low + high) // 2
        if has_enough_with_at_most(mid):
            answer = mid
            high = mid - 1
        else:
            low = mid + 1

    return answer
