def findKthSmallest(coins, k):
    from math import gcd

    n = len(coins)
    lcms = []
    signs = []

    for mask in range(1, 1 << n):
        cur_lcm = 1
        bits = 0

        for i, coin in enumerate(coins):
            if mask & (1 << i):
                cur_lcm = cur_lcm // gcd(cur_lcm, coin) * coin
                bits += 1

        lcms.append(cur_lcm)
        signs.append(1 if bits % 2 == 1 else -1)

    def count_leq(amount):
        total = 0
        for lcm_value, sign in zip(lcms, signs):
            total += sign * (amount // lcm_value)
        return total

    left, right = 1, min(coins) * k

    while left < right:
        mid = (left + right) // 2

        if count_leq(mid) >= k:
            right = mid
        else:
            left = mid + 1

    return left
