def minimumString(a: str, b: str, c: str) -> str:
    from itertools import permutations

    def overlap(x: str, y: str) -> int:
        for k in range(min(len(x), len(y)), 0, -1):
            if x[len(x) - k:] == y[:k]:
                return k
        return 0

    def merge(x: str, y: str) -> str:
        k = overlap(x, y)
        return x + y[k:]

    strings = []
    for s in (a, b, c):
        if s not in strings:
            strings.append(s)

    strings = [
        s for s in strings
        if not any(other != s and s in other for other in strings)
    ]

    best = None

    for order in permutations(strings):
        cur = order[0]
        for nxt in order[1:]:
            cur = merge(cur, nxt)

        if best is None or (len(cur), cur) < (len(best), best):
            best = cur

    return best
