def maximumXorProduct(a: int, b: int, n: int) -> int:
    MOD = 10**9 + 7
    x = 0

    for i in range(n - 1, -1, -1):
        ai = (a >> i) & 1
        bi = (b >> i) & 1
        bit = 1 << i

        if ai == bi:
            if ai == 0:
                x |= bit
        else:
            cur_a = a ^ x
            cur_b = b ^ x

            if cur_a < cur_b:
                if ai == 0:
                    x |= bit
            else:
                if ai == 1:
                    x |= bit

    return ((a ^ x) * (b ^ x)) % MOD
