import sys

def solve():
    input = sys.stdin.buffer.readline

    N, Q = map(int, input().split())
    S = input().strip()

    # bad[i] = 1 if S[i] == S[i+1] in 1-indexed boundary i
    bad = [0] * (N + 1)
    bit = [0] * (N + 1)

    for i in range(N - 1):
        if S[i] == S[i + 1]:
            idx = i + 1
            bad[idx] = 1
            bit[idx] += 1

    # Build Fenwick tree
    for i in range(1, N + 1):
        j = i + (i & -i)
        if j <= N:
            bit[j] += bit[i]

    def add(idx, val):
        while idx <= N:
            bit[idx] += val
            idx += idx & -idx

    def prefix_sum(idx):
        res = 0
        while idx > 0:
            res += bit[idx]
            idx -= idx & -idx
        return res

    def toggle(idx):
        if bad[idx]:
            bad[idx] = 0
            add(idx, -1)
        else:
            bad[idx] = 1
            add(idx, 1)

    ans = []

    for _ in range(Q):
        t, L, R = map(int, input().split())

        if t == 1:
            if L > 1:
                toggle(L - 1)
            if R < N:
                toggle(R)
        else:
            if prefix_sum(R - 1) - prefix_sum(L - 1) == 0:
                ans.append("Yes")
            else:
                ans.append("No")

    print("\n".join(ans))

