def buildMarblePositions(nums, moveFrom, moveTo):
    parent = {}
    size = {}
    occupied = {}

    for x in nums:
        if x not in parent:
            parent[x] = x
            size[x] = 0
            occupied[x] = x
        size[x] += 1

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]

        while parent[x] != x:
            nxt = parent[x]
            parent[x] = root
            x = nxt

        return root

    for src, dst in zip(moveFrom, moveTo):
        if src == dst:
            continue

        root_src = occupied.get(src)
        if root_src is None:
            continue

        root_src = find(root_src)
        occupied[src] = root_src

        root_dst = occupied.get(dst)

        if root_dst is None:
            occupied[dst] = root_src
            del occupied[src]
        else:
            root_dst = find(root_dst)
            occupied[dst] = root_dst

            if root_src == root_dst:
                continue

            if size[root_src] >= size[root_dst]:
                parent[root_dst] = root_src
                size[root_src] += size[root_dst]
                new_root = root_src
            else:
                parent[root_src] = root_dst
                size[root_dst] += size[root_src]
                new_root = root_dst

            occupied[dst] = new_root
            del occupied[src]

    return sorted(occupied.keys())
