def maximumProductSum(nums):
    n = len(nums)

    spf = list(range(n + 1))
    if n >= 1:
        spf[1] = 1

    limit = int(n ** 0.5)
    for p in range(2, limit + 1):
        if spf[p] == p:
            for multiple in range(p * p, n + 1, p):
                if spf[multiple] == multiple:
                    spf[multiple] = p

    def squarefree_part(x):
        part = 1
        while x > 1:
            p = spf[x]
            odd = 0
            while x % p == 0:
                x //= p
                odd ^= 1
            if odd:
                part *= p
        return part

    group_sums = {}
    for i, value in enumerate(nums, 1):
        key = squarefree_part(i)
        group_sums[key] = group_sums.get(key, 0) + value

    return max(group_sums.values())
