                return remaining == 0

            value = 0
            for end in range(pos, length):
                value = value * 10 + (ord(s[end]) - 48)
                if value > remaining:
                    break
                if dfs(end + 1, remaining - value):
                    return True

            return False

        return dfs(0, target)

    result = 0
    for i in range(1, n + 1):
        square = i * i
        if can_partition(square, i):
            result += square

    return result
