def findMaximumNumber(k: int, x: int) -> int:
    def total_price(n: int) -> int:
        total = 0
        pos = x  # 1-indexed bit position from the right

        while pos <= n.bit_length():
            half = 1 << (pos - 1)
            period = half << 1

            cycles, rem = divmod(n + 1, period)
            total += cycles * half
            if rem > half:
                total += rem - half

            pos += x

        return total

    lo, hi = 0, 1

    while total_price(hi) <= k:
        hi <<= 1

    while lo < hi:
        mid = (lo + hi + 1) // 2
        if total_price(mid) <= k:
            lo = mid
        else:
            hi = mid - 1

    return lo
