import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, H, W = data[0], data[1], data[2]
    tiles = []
    p = 3
    for _ in range(N):
        tiles.append((data[p], data[p + 1]))
        p += 2

    cells = H * W
    full_mask = (1 << cells) - 1
    all_tiles = (1 << N) - 1

    areas = []
    shapes = []
    for a, b in tiles:
        areas.append(a * b)
        shapes.append((min(a, b), max(a, b)))

    possible = [0] * (all_tiles + 1)
    possible[0] = 1
    for mask in range(1, all_tiles + 1):
        lsb = mask & -mask
        i = lsb.bit_length() - 1
        prev = mask ^ lsb
        possible[mask] = possible[prev] | (possible[prev] << areas[i])

    placements = [[] for _ in range(cells)]

    for i, (a, b) in enumerate(tiles):
        orientations = [(a, b)] if a == b else [(a, b), (b, a)]
        for h, w in orientations:
            if h > H or w > W:
                continue
            row_bits = (1 << w) - 1
            for r in range(H - h + 1):
                for c in range(W - w + 1):
                    mask = 0
                    for dr in range(h):
                        mask |= row_bits << ((r + dr) * W + c)
                    placements[r * W + c].append((i, mask))

    failed = set()

    def dfs(covered, used, covered_count):
        if covered == full_mask:
            return True

        state = (covered, used)
        if state in failed:
            return False

        need = cells - covered_count
        unused = all_tiles ^ used

        if ((possible[unused] >> need) & 1) == 0:
            failed.add(state)
            return False

        empty = (~covered) & full_mask
        pos = (empty & -empty).bit_length() - 1

        for i, tmpl_mask in placements[pos]:
            bit = 1 << i
            if used & bit:
                continue

            redundant = False
            for j in range(i):
                if shapes[j] == shapes[i] and not (used & (1 << j)):
                    redundant = True
                    break
            if redundant:
                continue

            if covered & tmpl_mask:
                continue

            if dfs(covered | tmpl_mask, used | bit, covered_count + areas[i]):
                return True

        failed.add(state)
        return False

    print("Yes" if dfs(0, 0, 0) else "No")

solve()

