    INF = 10**18
    ans = INF

    dot_cnt = [0] * W
    x_cnt = [0] * W
    last_rows = deque()

    for _ in range(H):
        s = input().strip()

        # Check horizontal segments
        dot_pref = [0] * (W + 1)
        x_pref = [0] * (W + 1)

        for j, ch in enumerate(s):
            dot_pref[j + 1] = dot_pref[j] + (ch == '.')
            x_pref[j + 1] = x_pref[j] + (ch == 'x')

        for j in range(W - K + 1):
            if x_pref[j + K] == x_pref[j]:
                ans = min(ans, dot_pref[j + K] - dot_pref[j])

        # Add current row to vertical sliding window
        for j, ch in enumerate(s):
            if ch == '.':
                dot_cnt[j] += 1
            elif ch == 'x':
                x_cnt[j] += 1

        last_rows.append(s)

        if len(last_rows) > K:
            old = last_rows.popleft()
            for j, ch in enumerate(old):
                if ch == '.':
                    dot_cnt[j] -= 1
                elif ch == 'x':
                    x_cnt[j] -= 1

        # Check vertical segments
        if len(last_rows) == K:
            for j in range(W):
                if x_cnt[j] == 0:
                    ans = min(ans, dot_cnt[j])

    print(-1 if ans == INF else ans)

