def numberOfPowerfulInt(start: int, finish: int, limit: int, s: str) -> int:
    suffix = int(s)
    width = len(s)
    scale = 10 ** width
    base = limit + 1

    def count_prefixes_leq(n: int) -> int:
        if n < 0:
            return 0

        digits = str(n)
        length = len(digits)

        power = [1] * (length + 1)
        for i in range(1, length + 1):
            power[i] = power[i - 1] * base

        count = 0

        for i, ch in enumerate(digits):
            digit = int(ch)
            remaining = length - i - 1

            if digit > limit:
                count += base * power[remaining]
                return count

            count += digit * power[remaining]

        return count + 1

    def count_up_to(x: int) -> int:
        if x < suffix:
            return 0

        max_prefix = (x - suffix) // scale
        return count_prefixes_leq(max_prefix)

    return count_up_to(finish) - count_up_to(start - 1)
