def minimumOperationsToMakeEqual(x: int, y: int) -> int:
    from collections import deque

    limit = max(x, y) * 11 + 10
    dist = [-1] * (limit + 1)
    dist[x] = 0

    queue = deque([x])

    while queue:
        cur = queue.popleft()

        if cur == y:
            return dist[cur]

        candidates = [cur - 1, cur + 1]

        if cur % 5 == 0:
            candidates.append(cur // 5)

        if cur % 11 == 0:
            candidates.append(cur // 11)

        for nxt in candidates:
            if 0 <= nxt <= limit and dist[nxt] == -1:
                dist[nxt] = dist[cur] + 1
                queue.append(nxt)

    return -1
