        freq[num] = freq.get(num, 0) + 1
        if freq[num] == 1:
            distinct += 1

        if right >= k:
            left_num = nums[right - k]
            window_sum -= left_num
            freq[left_num] -= 1

            if freq[left_num] == 0:
                del freq[left_num]
                distinct -= 1

        if right >= k - 1 and distinct >= m:
