def canTraverseAllPairs(nums):
    n = len(nums)
    if n == 1:
        return True
    if 1 in nums:
        return False

    max_num = max(nums)

    # Smallest prime factor sieve
    spf = [0] * (max_num + 1)
    for i in range(2, max_num + 1):
        if spf[i] == 0:
            spf[i] = i
            if i * i <= max_num:
                for j in range(i * i, max_num + 1, i):
                    if spf[j] == 0:
                        spf[j] = i

    parent = list(range(n))
    size = [1] * n
    components = n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        nonlocal components
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
        components -= 1

    first_index_for_prime = {}

    for i, num in enumerate(nums):
        x = num
        while x > 1:
            p = spf[x]
            if p in first_index_for_prime:
                union(i, first_index_for_prime[p])
            else:
                first_index_for_prime[p] = i

            while x % p == 0:
                x //= p

        if components == 1:
            return True

    return components == 1
