def productQueries(queries):
    def stats(n):
        count = 0
        exp_sum = 0

        for b in range(n.bit_length()):
            period = 1 << (b + 1)
            half = 1 << b

            full_cycles = n // period
            rem = n % period

            ones = full_cycles * half + max(0, rem - half + 1)
            count += ones
            exp_sum += b * ones

        return count, exp_sum

    def prefix_exp(t):
        if t <= 0:
            return 0

        hi = 1
        while stats(hi)[0] < t:
            hi <<= 1

        lo = 0
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if stats(mid)[0] <= t:
                lo = mid
            else:
                hi = mid - 1

        count, exp_sum = stats(lo)
        remaining = t - count
        n = lo + 1

        for b in range(n.bit_length()):
            if remaining == 0:
                break
            if (n >> b) & 1:
                exp_sum += b
                remaining -= 1

        return exp_sum

    cache = {}
    answer = []

    for left, right, mod in queries:
        if left not in cache:
            cache[left] = prefix_exp(left)
        if right + 1 not in cache:
            cache[right + 1] = prefix_exp(right + 1)

        exponent = cache[right + 1] - cache[left]
        answer.append(pow(2, exponent, mod))

    return answer
