def maxIncreasingGroups(usageLimits):
    n = len(usageLimits)
    a = sorted(usageLimits)

    prefix = [0] * (n + 1)
    for i, x in enumerate(a):
        prefix[i + 1] = prefix[i] + x

    # cap[t] = sum_i min(usageLimits[i], t)
    cap = [0] * (n + 1)
    p = 0
    for t in range(1, n + 1):
        while p < n and a[p] < t:
            p += 1
        cap[t] = prefix[p] + t * (n - p)

    def feasible(k):
        for t in range(1, k + 1):
            needed = t * (2 * k - t + 1) // 2
            if cap[t] < needed:
                return False
        return True

    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1

    return lo
