def specialPerm(nums):
    n = len(nums)
    MOD = 10**9 + 7

    compatible = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                compatible[i][j] = True

    size = 1 << n
    dp = [[0] * n for _ in range(size)]

    for i in range(n):
        dp[1 << i][i] = 1

    for mask in range(size):
        for last in range(n):
            current = dp[mask][last]
            if current == 0:
                continue

            for nxt in range(n):
