def maxPartitions(s: str, k: int) -> int:
    from functools import lru_cache
    import sys

    n = len(s)
    if n == 0:
        return 0
    if k >= 26:
        return 1

    sys.setrecursionlimit(max(sys.getrecursionlimit(), 2 * n + 10))

    bits = [1 << (ord(ch) - ord('a')) for ch in s]

    # firsts[i] = positions of distinct characters in s[i:], ordered by first occurrence
    firsts = [()] * (n + 1)
    seen = 0
    for i in range(n - 1, -1, -1):
        b = bits[i]
        if seen & b:
            firsts[i] = firsts[i + 1]
        else:
            seen |= b
            firsts[i] = (i,) + firsts[i + 1]

    @lru_cache(maxsize=None)
    def future_cuts(i: int, mask: int) -> int:
        """Number of future cuts from s[i:] when current segment has chars in mask."""
        if i >= n:
            return 0

        need = k - mask.bit_count() + 1
        new_count = 0

        for pos in firsts[i]:
            b = bits[pos]
            if mask & b:
                continue

            new_count += 1
            if new_count == need:
                return 1 + future_cuts(pos + 1, b)

        return 0

    ans = 1
    current_mask = 0
    cuts_before = 0

    for i, original_bit in enumerate(bits):
        current_size = current_mask.bit_count()

        # Change s[i] to any lowercase letter.
        for c in range(26):
            changed_bit = 1 << c

            if current_size == k and not (current_mask & changed_bit):
                total_cuts = cuts_before + 1 + future_cuts(i + 1, changed_bit)
            else:
                total_cuts = cuts_before + future_cuts(i + 1, current_mask | changed_bit)

            ans = max(ans, total_cuts + 1)

        # Continue scan with original character.
        if (current_mask & original_bit) or current_size < k:
            current_mask |= original_bit
        else:
            cuts_before += 1
            current_mask = original_bit

    return ans
```

