        if min_col == a:
            left = "A"
        elif min_col == b:
            left = "B"
        else:
            left = "C"
        patterns[left].append((a, b, c))

    grid = [["."] * N for _ in range(N)]
    fail = set()

    def dfs(row, mask_a, mask_b, mask_c, occupied):
        key = (row, mask_a, mask_b, mask_c, occupied)
        if key in fail:
            return False

        if row == N:
            ok = mask_a == full and mask_b == full and mask_c == full and occupied == full
            if not ok:
                fail.add(key)
            return ok

        for a, b, c in patterns[R[row]]:
            cols = (a, b, c)
            masks = [mask_a, mask_b, mask_c]
            new_occupied = occupied
            ok = True

            for idx, pos in enumerate(cols):
                bit = 1 << pos
                if masks[idx] & bit:
