                masks[idx] |= bit
                new_occupied |= bit

            if not ok:
                continue

            for idx, pos in enumerate(cols):
                grid[row][pos] = chars[idx]

            if dfs(row + 1, masks[0], masks[1], masks[2], new_occupied):
                return True

            for pos in cols:
                grid[row][pos] = "."

        fail.add(key)
        return False

    if dfs(0, 0, 0, 0):
