def findMinimumOperations(s1: str, s2: str, s3: str) -> int:
    min_len = min(len(s1), len(s2), len(s3))
    lcp_len = 0
    while lcp_len < min_len and s1[lcp_len] == s2[lcp_len] == s3[lcp_len]:
        lcp_len += 1

    if lcp_len == 0:
        return -1

    return len(s1) + len(s2) + len(s3) - 3 * lcp_len
