def findMinimumOperations(s1: str, s2: str, s3: str) -> int:
    # To make three strings equal by deleting the rightmost characters,
    # they must share a common prefix.
    # The first characters must be the same, otherwise they can never be equal.
    if s1[0] != s2[0] or s1[0] != s3[0] or s2[0] != s3[0]:
        return -1

    # Find the length of the longest common prefix among s1, s2, and s3
    min_len = min(len(s1), len(s2), len(s3))
    common_prefix_length = 0

    for i in range(min_len):
        if s1[i] == s2[i] == s3[i]:
            common_prefix_length += 1
        else:
            break

    # Total operations needed is the sum of characters to delete from each string
    # to reach the common prefix.
    total_len = len(s1) + len(s2) + len(s3)
    return total_len - (3 * common_prefix_length)
```

