def findMissingAndRepeatedValues(grid):
    n = len(grid)
    total_elements = n * n

    # Use a frequency map or a set to track occurrences
    # Since n is small (up to 50), n^2 is 2500, making this efficient.
    counts = {}

    repeated = -1
    missing = -1

    # Flatten the grid and count occurrences
    for row in grid:
        for val in row:
            counts[val] = counts.get(val, 0) + 1
            if counts[val] == 2:
                repeated = val

    # Find the missing number in the range [1, n^2]
    for i in range(1, total_elements + 1):
        if i not in counts:
            missing = i
            break

    return [repeated, missing]
```

