def countPrefixSuffixPairs(words):
    """
    Counts the number of index pairs (i, j) such that i < j and 
    words[i] is both a prefix and a suffix of words[j].
    """
    def isPrefixAndSuffix(str1, str2):
        # A prefix and suffix must have length <= the main string
        if len(str1) > len(str2):
            return False
        # Check if str1 is both prefix and suffix of str2
        return str2.startswith(str1) and str2.endswith(str1)

    count = 0
    n = len(words)

    # Iterate through all pairs (i, j) where i < j
    for i in range(n):
        for j in range(i + 1, n):
            if isPrefixAndSuffix(words[i], words[j]):
                count += 1

    return count
```

