def canTraverseAllPairs(nums: list[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True

    # Disjoint Set Union (DSU) to group connected indices
    parent = list(range(n))
    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    # Map each prime factor to the first index in nums that contains it
    prime_to_index = {}

    for i, val in enumerate(nums):
        if val == 1:
            return False

        # Prime factorization
        d = 2
        temp = val
        while d * d <= temp:
            if temp % d == 0:
                if d in prime_to_index:
                    union(i, prime_to_index[d])
                else:
                    prime_to_index[d] = i
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            if temp in prime_to_index:
                union(i, prime_to_index[temp])
            else:
                prime_to_index[temp] = i

    # Check if all indices are in the same component
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False
    return True
