import sys

def solve():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return

    N = int(data[0])
    H = int(data[1])
    W = int(data[2])

    tiles = []
    idx = 3
    for _ in range(N):
        a = int(data[idx])
        b = int(data[idx+1])
        tiles.append((a, b))
        idx += 2

    # grid representation: 0 for empty, 1 for occupied
    grid = [[0] * W for _ in range(H)]
    used = [False] * N

    def backtrack():
        # Find the first empty cell
        r, c = -1, -1
        for i in range(H):
            for j in range(W):
                if grid[i][j] == 0:
                    r, c = i, j
                    break
            if r != -1:
                break

        # If no empty cell is found, the grid is completely covered
        if r == -1:
            return True

        # Try placing each unused tile
        for i in range(N):
            if used[i]:
                continue

            a, b = tiles[i]
            # Try both orientations (a, b) and (b, a)
            orientations = {(a, b), (b, a)}
            for h, w in orientations:
                if r + h <= H and c + w <= W:
                    # Check if all required cells are free
                    can_place = True
                    for dr in range(h):
                        for dc in range(w):
                            if grid[r + dr][c + dc] == 1:
                                can_place = False
                                break
                        if not can_place:
                            break

                    if can_place:
                        # Place tile
                        for dr in range(h):
                            for dc in range(w):
                                grid[r + dr][c + dc] = 1
                        used[i] = True

                        if backtrack():
                            return True

                        # Unplace tile
                        for dr in range(h):
                            for dc in range(w):
                                grid[r + dr][c + dc] = 0
                        used[i] = False

        return False

    if backtrack():
        print("Yes")
    else:
        print("No")

