import sys

def solve():
    # Read input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    H = int(input_data[1])
    W = int(input_data[2])

    tiles = []
    idx = 3
    for _ in range(N):
        tiles.append((int(input_data[idx]), int(input_data[idx+1])))
        idx += 2

    # Grid represented by a 2D list of booleans
    grid = [[False for _ in range(W)] for _ in range(H)]

    def can_place(r, c, h, w):
        if r + h > H or c + w > W:
            return False
        for i in range(r, r + h):
            for j in range(c, c + w):
                if grid[i][j]:
                    return False
        return True

    def place(r, c, h, w, val):
        for i in range(r, r + h):
            for j in range(c, c + w):
                grid[i][j] = val

    used = [False] * N

    def backtrack():
        # Find the first empty cell
        r, c = -1, -1
        found = False
        for i in range(H):
            for j in range(W):
                if not grid[i][j]:
                    r, c = i, j
                    found = True
                    break
            if found: break

        # If no empty cells, the grid is full
        if not found:
            return True

        for i in range(N):
            if not used[i]:
                used[i] = True
                # Try original orientation
                ah, aw = tiles[i]
                for h, w in set([(ah, aw), (aw, ah)]):
                    if can_place(r, c, h, w):
                        place(r, c, h, w, True)
                        if backtrack():
                            return True
                        place(r, c, h, w, False)
                used[i] = False

        return False

    if backtrack():
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
