def getSmallestString(s: str, k: int) -> str:
    res = []
    for char in s:
        curr = ord(char) - ord("a")
        # Try to pick the smallest possible character starting from 'a'
        for target in range(26):
            # Calculate cyclic distance between curr and target
            diff = abs(curr - target)
            dist = min(diff, 26 - diff)
            if dist <= k:
                res.append(chr(ord("a") + target))
                k -= dist
                break
    return "".join(res)
